// GET ?q=<text> searches HubSpot products (name or Eclipse product id).
// GET ?e_product_id=106331 lists every Eclipse order generation (HubSpot
// deal) with a line item for that product. Read-only, HubSpot only.
const q = $input.first().json.query || {};
const stop = (statusCode, error) => [{ json: { ok: false, mode: 'error', statusCode, body: { success: false, error, step: 'validate' } } }];
const pid = String(q.e_product_id || '').trim();
if (pid) {
  if (!/^\d+$/.test(pid)) return stop(400, 'e_product_id must be a number.');
  const filter = { filterGroups: [{ filters: [
    { propertyName: 'e_product_id_', operator: 'EQ', value: pid },
    { propertyName: 'e_sorder_id', operator: 'HAS_PROPERTY' },
  ] }] };
  return [{ json: { ok: true, mode: 'deals', e_product_id: pid, filter } }];
}
const text = String(q.q || '').trim().replace(/\s+/g, ' ');
if (text.length < 2) return stop(400, 'Type at least 2 characters (q), or pass e_product_id.');
// A leading dot (.1000) looks up that Eclipse product id only, like the
// product-inquiry search: no name or description match.
// A dot followed by anything but digits matches nothing.
if (text.charAt(0) === '.' && !/^\.\s*\d+$/.test(text)) return [{ json: { ok: false, mode: 'error', statusCode: 200, body: { success: true, q: text, total: 0, products: [] } } }];
const dot = text.match(/^\.\s*(\d+)$/);
if (dot) return [{ json: { ok: true, mode: 'search', q: dot[1], filter: { filterGroups: [{ filters: [{ propertyName: 'e_product_id_', operator: 'EQ', value: dot[1] }] }] } } }];
// Each word must appear in the name (or each in the description); a number
// also matches the Eclipse product id exactly. HubSpot allows 5 groups and
// 6 filters per group, so only the first 5 words count.
const words = text.split(' ').map((w) => w.replace(/[*"]/g, '')).filter(Boolean).slice(0, 5);
const has = { propertyName: 'e_product_id_', operator: 'HAS_PROPERTY' };
const groups = ['name', 'description'].map((prop) => ({
  filters: [has].concat(words.map((w) => ({ propertyName: prop, operator: 'CONTAINS_TOKEN', value: '*' + w + '*' }))),
}));
if (/^\d+$/.test(text)) groups.unshift({ filters: [{ propertyName: 'e_product_id_', operator: 'EQ', value: text }] });
return [{ json: { ok: true, mode: 'search', q: text, filter: { filterGroups: groups } } }];

// Products for the search box: an exact product id match first, then
// HubSpot's order. Only products that carry an Eclipse id.
const v = $('Validate').first().json;
const items = $input.all().map((i) => i.json || {});
const err = items.find((j) => j.error);
if (err) return [{ json: { statusCode: 502, body: { success: false, error: 'HubSpot product search failed: ' + err.error + ' ' + JSON.stringify(err.message || '').substring(0, 300), step: 'searchProducts' } } }];
const rows = [];
for (const j of items) {
  if (Array.isArray(j.results)) rows.push(...j.results);
  else if (j.id && j.properties) rows.push(j);
}
// total: every match in HubSpot (the page shows the first 25).
const total = items.reduce((t, j) => (j.total != null ? Number(j.total) : t), null);
const seen = new Set();
const products = [];
for (const r of rows) {
  const p = r.properties || {};
  const id = String(p.e_product_id_ || '').trim();
  if (!id || seen.has(id)) continue;
  seen.add(id);
  products.push({
    e_product_id: id,
    name: p.name || '',
    description: p.description || '',
    uom: p.e_uom || '',
    status: p.e_product_status || '',
    hs_product_id: String(r.id),
  });
}
products.sort((a, b) => (b.e_product_id === v.q) - (a.e_product_id === v.q));
return [{ json: { statusCode: 200, body: { success: true, q: v.q, total: total == null ? products.length : total, products } } }];

// Line items for the product → one entry per order generation
// (e_sorder_id, e.g. S2738846.0001) with the product's total quantity on it.
// Quote copies of deal lines carry no e_sorder_id, so the search skips them.
const v = $('Validate').first().json;
const items = $input.all().map((i) => i.json || {});
const err = items.find((j) => j.error);
if (err) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'HubSpot line item search failed: ' + err.error + ' ' + JSON.stringify(err.message || '').substring(0, 300), step: 'searchLines' } } }];
const rows = [];
for (const j of items) {
  if (Array.isArray(j.results)) rows.push(...j.results);
  else if (j.id && j.properties) rows.push(j);
}
const gens = {};
for (const r of rows) {
  const p = r.properties || {};
  const id = String(p.e_sorder_id || '').trim().toUpperCase();
  if (!/^S\d+\.\d+$/.test(id)) continue;
  const g = gens[id] || (gens[id] = { qty: 0, uom: '' });
  const q = Number(p.quantity);
  if (isFinite(q)) g.qty += q;
  if (!g.uom && p.e_uom) g.uom = String(p.e_uom).toLowerCase();
}
const ids = Object.keys(gens);
// HubSpot search stops at 10,000 results.
const truncated = rows.length >= 10000;
if (!ids.length) return [{ json: { ok: false, statusCode: 200, body: { success: true, e_product_id: v.e_product_id, orders: [], line_count: 0, truncated: false } } }];
return [{ json: { ok: true, ids: ids.join(','), gens, line_count: rows.length, truncated } }];

// Deals grouped into orders like customer-orders: newest order date first,
// generations by number. Deals archived in Eclipse (e_sorder_deleted) are
// left out.
const v = $('Validate').first().json;
const picked = $('Pick orders').first().json;
const items = $input.all().map((i) => i.json || {});
const err = items.find((j) => j.error);
if (err) return [{ json: { statusCode: 502, body: { success: false, error: 'HubSpot deal read failed: ' + err.error + ' ' + JSON.stringify(err.message || '').substring(0, 300), step: 'readDeals' } } }];
const rows = [];
for (const j of items) {
  if (Array.isArray(j.results)) rows.push(...j.results);
  else if (j.id && j.properties) rows.push(j);
}
const num = (x) => (x == null || x === '' || !isFinite(Number(x)) ? null : Number(x));
const str = (x) => (x == null ? '' : String(x).trim());
const orders = {};
for (const r of rows) {
  const p = r.properties || {};
  if (str(p.e_sorder_deleted)) continue;
  const id = str(p.e_sorder_id).toUpperCase();
  const m = id.match(/^(S\d+)\.(\d+)$/);
  if (!m) continue;
  const o = orders[m[1]] || (orders[m[1]] = { order_id: m[1], order_date: '', generations: [] });
  const g = picked.gens[id] || {};
  const gen = {
    e_sorder_id: id,
    generation_id: num(p.e_generation_number) != null ? num(p.e_generation_number) : Number(m[2]),
    status: str(p.e_status),
    order_date: str(p.e_order_date).slice(0, 10),
    invoice_number: str(p.e_invoice_number),
    ship_to_id: str(p.e_ship_to_id),
    ship_to_name: str(p.e_ship_to_name),
    bill_to_id: str(p.e_bill_to_id),
    bill_to_name: str(p.bill_to_name),
    po: str(p.e_po_number),
    sales_total: num(p.e_sales_total),
    qty: g.qty == null ? null : g.qty,
    uom: g.uom || '',
    hs_deal_id: String(r.id),
  };
  o.generations.push(gen);
  if (gen.order_date && (!o.order_date || gen.order_date < o.order_date)) o.order_date = gen.order_date;
}
const list = Object.values(orders);
list.forEach((o) => o.generations.sort((a, b) => a.generation_id - b.generation_id));
list.sort((a, b) => (b.order_date || '').localeCompare(a.order_date || '') || b.order_id.localeCompare(a.order_id));
return [{ json: { statusCode: 200, body: { success: true, e_product_id: v.e_product_id, orders: list, line_count: picked.line_count, truncated: picked.truncated } } }];
